commands.command:
sudo -u postgres psql -v ON_ERROR_STOP=1 <<SQL
CREATE ROLE replicator WITH REPLICATION LOGIN PASSWORD '$(cat /tmp/repl_pw.txt)';
SQL

sudo -u postgres psql -v ON_ERROR_STOP=1 <<'SQL'
CREATE TABLE repl_test (id serial PRIMARY KEY, note text, created_at timestamptz DEFAULT now());
INSERT INTO repl_test (note) VALUES ('hello from primary'), ('streaming replication check');
SELECT * FROM repl_test;
SQL
